\vspace{-10pt}

\label{def:prelim_rfm}
The map $\Phi({\,\cdot\,};\alpha)=\Phi({\,\cdot\,};\alpha,{\{\theta_m\}})\colon\mathcal{X}\to\mathcal{Y} $ given by
\begin{equation}\label{eq:rf_model}
    u\mapsto \Phi(u;\alpha)\coloneqq \frac{1}{M}\sum_{m=1}^M\alpha_m\varphi(u;\theta_m)
\end{equation}
is a \emph{random feature model} (RFM) with coefficients $\alpha\in\mathbb{R}^M$ and fixed realizations ${\{\theta_m\}}\sim\mu^{\otimes M}$.

\label{def:prelim_emp}
    Writing $Y=\{y_n\}$ for the collection of observed output data and fixing a regularization parameter $\lambda > 0$, the \define{regularized $Y$-empirical risk} of $\alpha\in\mathbb{R}^M$ is given by
    \begin{align}\label{eq:prelim_reg}
        \mathscr{R}_N^\lambda(\alpha;Y)\coloneqq \frac1N \sum_{n=1}^N \Vert y_n - \Phi(u_n;\alpha)\Vert_{\mathcal{Y}}^2 +\lambda \normtemp{\alpha}_M^2\,,\quad\text{where}\quad \normtemp{\alpha}^2_M\coloneqq \frac{1}{M}\sum_{m=1}^M\abstemp{\alpha_m}^2
    \end{align} 
    is a scaled Euclidean norm  on $\mathbb{R}^M$. The \define{regularized $\mathcal{G}$-empirical risk}, $\mathscr{R}_N^\lambda(\alpha;\mathcal{G})$, is defined analogously with $\mathcal{G}(u_n)$ in place of $y_n$. In the absence of regularization, i.e., $\lambda = 0$, these expressions define the \define{$Y$-empirical risk} and \define{$\mathcal{G}$-empirical risk}, denoted by $\mathscr{R}_N(\alpha;Y)$ and $\mathscr{R}_N(\alpha;\mathcal{G})$, respectively.

\label{ass:joint_dist_noise}
    The joint distribution $\mathcal{P}\in\mathscr{P}(\mathcal{X}\times \mathcal{Y})$ of the random variable $(u,y)\sim\mathcal{P}$ is given by $u\sim \nu$ with $\nu\in\mathscr{P}(\mathcal{X})$ and $y=\mathcal{G}(u) + \eta$. Here, $\mathcal{G}$ satisfies Assumption~\ref{ass:misspec}.
    The additive noise $\eta$ is a random variable in $\mathcal{Y}$ that is conditionally centered, $\operatorname{\mathbb{E}}[\eta\, \vert \, u]=0$, and is subexponential: $\normtemp{\eta}_{\psi_1(\mathcal{Y})}<\infty$; see \eqref{eq:app_def_subexp_norm_vec} for the definition of $\Vert {\,\cdot\,} \Vert_{\psi_1(\mathcal{Y})}$.

\label{sec:main_error_bound}
For any $\mathcal{G}$, define the \emph{$\mathcal{G}$-population risk functional} or \emph{$\mathcal{G}$-population squared error} by
\begin{equation}\label{eq:risk_pop_truth}
    \mathscr{R}(\alpha;\mathcal{G})\coloneqq \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\alpha,{\{\theta_m\}})}_{\mathcal{Y}}^2 \quad\text{for}\quad \alpha\in\mathbb{R}^M\,.
\end{equation}

\label{thm:error_bound_total_G}
    Suppose that $\mathcal{G} = \rho+\mathcal{G}_{\mathcal{H}} $ satisfies Assumption~\ref{ass:misspec}. Fix a failure probability $\delta\in(0,1)$, regularization strength $\lambda\in(0,1)$, and sample size $N$. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ be the $M$ random feature parameters and $\{(u_n,y_n)\}\sim\mathcal{P}^{\otimes N}$ be the data according to Assumption~\ref{ass:joint_dist_noise}. For $\Phi$ the RFM~\eqref{eq:rf_model} satisfying Assumption~\ref{ass:rf}, let $\widehat{\alpha}
    \in \mathbb{R}^M$ be the minimizer of the regularized $Y$-empirical risk $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by \eqref{eq:prelim_reg}. If $M \ge \lambda^{-1}\log(32/\delta)$ and $N\geq \lambda^{-2}\log(16/\delta)$, then
    \begin{equation}\label{eq:error_bound_total_G}
        \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\widehat{\alpha},{\{\theta_m\}})}_{\mathcal{Y}}^2  \leq 79e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L^\infty_\nu}^2 + 2\beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\lambda
    \end{equation}
    with probability at least $1-\delta$, where
    \begin{equation}\label{eq:alphabd_noisy_const}
        \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta) \coloneqq 328 \normtemp{\mathcal{G}_{\mathcal{H}}}_{\mathcal{H}}^2
            + 2023e^{3}\normtemp{\eta}_{\psi_1(\mathcal{Y})}^2 + 8\lambda^{-1}\operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\rho(u)}_{\mathcal{Y}}^2   + 18\lambda \normtemp{\rho}_{L^\infty_\nu}^2
    \end{equation}
    is a function of $\rho$, $\lambda$, $\mathcal{G}_{\mathcal{H}}$, and the law of the noise variable $\eta$.

In the well-specified setting, that is, $\mathcal{G}-\mathcal{G}_{\mathcal{H}}=\rho\equiv 0$, the factor $\beta$ in Thm.~\eqref{thm:error_bound_total_G} satisfies the uniform bound
\begin{equation}\label{eq:beta_well}
    \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\leq B\coloneqq 328\normtemp{\mathcal{G}}_{\mathcal{H}}^2 + 2023e^{3}\normtemp{\eta}_{\psi_1(\mathcal{Y})}^2\,.
\end{equation}
In particular, the constant $B$ does not depend on $\lambda$ in this case. Otherwise, $\beta$ in general depends on $\lambda$. We can characterize this dependence precisely if it is known that $\mathcal{G}\in L^\infty_\nu(\mathcal{X};\mathcal{Y})$. In this case, Assumption~\ref{ass:misspec} is satisfied with $\rho\coloneqq \mathcal{G}-\mathcal{G}_{\mathcal{H}}$ \emph{for any} $\mathcal{G}_{\mathcal{H}}\in\mathcal{H}$. Choosing $\mathcal{G}_{\mathcal{H}}=\mathcal{G}_\vartheta|_{\vartheta=\lambda}$ as in {\bf SM}~\ref{app:rkhs} (which is optimal in the sense described there) and a short calculation deliver the bound
\begin{equation}\label{eq:beta_misspec}
    \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\lesssim \lambda^{-1}\lambda^{r\wedge 1} = \lambda^{-(1-r)_{+}}
\end{equation}
if $\mathcal{G}$ additionally satisfies a particular $r$-th order regularity condition (see Lem.~\ref{lem:rkhs_approx_rate} for the details). Here, $a_+\coloneqq\max(a,0)$ for any $a\in\mathbb{R}$. Thus, $\beta$ is uniformly bounded if $\mathcal{G}\in\mathcal{H}$ $(r\geq 1)$  and grows algebraically as a power of $\lambda^{-1}$ otherwise $(0\leq r<1)$.

\label{thm:error_bound_total_well}
    Instantiate the hypotheses and notation of Thm.~\ref{thm:error_bound_total_G}. Suppose that $\rho\equiv 0$ so that $\mathcal{G}\in\mathcal{H}$~\eqref{eq:prelim_rkhs}. If $M \ge \lambda^{-1}\log(32/\delta)$ and $N\geq \lambda^{-2}\log(16/\delta)$, then
    \begin{equation}\label{eq:error_bound_total_G_well}
        \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\widehat{\alpha})}_{\mathcal{Y}}^2 \leq 79e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L^\infty_\nu}^2 + 2B\bigr)\lambda\lesssim \lambda
    \end{equation}
    with probability at least $1-\delta$, where the constant $B\geq 0$ is defined by \eqref{eq:beta_well}.

\label{cor:error_bound_total_GH}
    Instantiate the hypotheses and notation of Thm.~\ref{thm:error_bound_total_G}. If $M \ge \lambda^{-1}\log(32/\delta)$ and $N\geq \lambda^{-2}\log(16/\delta)$, then there exists an absolute constant $C>1$ such that with probability at least $1-\delta$, it holds that
    \begin{equation}\label{eq:error_bound_total_GH}
        \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}_{\mathcal{H}}(u)-\Phi(u;\widehat{\alpha})}_{\mathcal{Y}}^2 \leq C\bigl(\normtemp{\mathcal{G}}_{L^\infty_\nu}^2 + 2 \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\lambda\,.
    \end{equation}

