\label{thm:main_consis_strong}
Suppose that $\mathcal{G}\in L^\infty_\nu(\mathcal{X};\mathcal{Y})$ belongs to the $L^2_\nu(\mathcal{X};\mathcal{Y})$-closure of $\mathcal{H}$~\eqref{eq:prelim_rkhs}. Let $\{\lambda_k\}_{k\in\mathbb{N}}\subset (0,1)$ be a sequence of positive regularization parameters such that $\sum_{k\in \mathbb{N}} \lambda_k < \infty$. For $\Phi$ the RFM~\eqref{eq:rf_model} satisfying Assumption~\ref{ass:rf} and for each $k$, let $\widehat{\alpha}^{(k)}\in\mathbb{R}^{M_k}$ be the trained RFM coefficients that minimize the regularized $Y$-empirical risk $\mathscr{R}_{N_k}^{\lambda_k}({\,\cdot\,};Y)$ given by \eqref{eq:prelim_reg} with $M_k\simeq \lambda_k^{-1} \log(2/\lambda_k)$ iid random features and $N_k \simeq \lambda_k^{-2} \log(2/\lambda_k)$ iid data pairs under Assumption~\ref{ass:joint_dist_noise}. It holds true that
\begin{equation}\label{eq:main_consis_strong}
    \lim_{k\to \infty} \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\widehat{\alpha}^{(k)})}_{\mathcal{Y}}^2 = 0\ \ \text{with probability one.}
\end{equation}

\label{thm:main_rates_slow}
    Suppose that $\mathcal{G} \in L^\infty_\nu(\mathcal{X};\mathcal{Y}) $ and that Assumption~\ref{ass:joint_dist_noise} holds. Additionally, assume that $\mathcal{G}\in \mathrm{Im}(\mathcal{K}^{r/2})$ for some $r>0$, where $\mathcal{K}$ is the integral operator corresponding to the kernel of RKHS $\mathcal{H}$~\eqref{eq:prelim_rkhs}. Fix $\delta\in(0,1)$ and $\lambda\in(0,1)$. For $\Phi$ the RFM~\eqref{eq:rf_model} satisfying Assumption~\ref{ass:rf}, let $\widehat{\alpha}\in \mathbb{R}^M$ minimize $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by \eqref{eq:prelim_reg}. If $M \ge \lambda^{-1}\log(32/\delta)$ and $N\geq \lambda^{-2}\log(16/\delta)$, then with probability at least $1-\delta$ it holds that
    \begin{equation}\label{eq:main_rates_slow}
        \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\widehat{\alpha})}_{\mathcal{Y}}^2\lesssim \lambda^{r\wedge 1}\,.
    \end{equation}
    The implied constant in \eqref{eq:main_rates_slow} depends only on $\normtemp{\mathcal{G}}_{L^\infty_\nu}$ and $\normtemp{\eta}_{\psi_1(\mathcal{Y})}$.

\label{cor:main_rates_strong}
Instantiate the hypotheses and notation of Thm.~\ref{thm:main_consis_strong}. Assume in addition that $\mathcal{G}\in \mathrm{Im}(\mathcal{K}^{r/2})$ for some $r>0$. Let $\{\lambda_k\}_{k\in\mathbb{N}}\subset (0,1)$ be a sequence of positive regularization parameters such that $\sum_{k\in \mathbb{N}} \lambda_k < \infty$. For each $k$, let $\widehat{\alpha}^{(k)}\in\mathbb{R}^{M_k}$ be the trained RFM coefficients with $M_k\simeq \lambda_k^{-1} \log(2/\lambda_k)$ and $N_k \simeq \lambda_k^{-2} \log(2/\lambda_k)$. It holds true that
\begin{equation}\label{eq:main_rates_strong}
    \limsup_{k\to \infty} \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{\operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u) - \Phi(u;\widehat{\alpha}^{(k)})}_{\mathcal{Y}}^2}{\lambda_k^{r\wedge 1}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right) <\infty\ \ \text{with probability one.}
\end{equation}

\label{prop:train_erm_bound_noisy}
Let Assumptions \ref{ass:rf} and \ref{ass:joint_dist_noise} hold. Suppose that $\mathcal{G} = \rho+\mathcal{G}_{\mathcal{H}} $ satisfies Assumption~\ref{ass:misspec}. Fix $\delta\in(0,1)$, $\lambda\in(0,1)$, $M\in\mathbb{N}$, and $N\in\mathbb{N}$. Let $\widehat{\alpha}\in \mathbb{R}^M$ be the minimizer of the regularized $Y$-empirical risk $\mathscr{R}_N^\lambda({\,\cdot\,};Y)$ given by \eqref{eq:prelim_reg}. If $M \ge \lambda^{-1}\log(16/\delta)$ and $N\geq \lambda^{-2}\log(8/\delta)$, then
\begin{equation}\label{eq:alphabd_noisy_risk}
    \mathscr{R}_N^\lambda(\widehat{\alpha};\mathcal{G}) \leq \lambda \beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)
\end{equation}
with probability at least $1-\delta$, where the multiplicative factor $\beta(\rho,\lambda, \mathcal{G}_{\mathcal{H}}, \eta)$ is given by \eqref{eq:alphabd_noisy_const}.

\label{cor:train_norm_bound_noisy}
    Instantiate the hypotheses  and notation of Prop.~\ref{prop:train_erm_bound_noisy}. Fix $\delta\in(0,1)$ and $\lambda\in(0,1)$. If $M \ge \lambda^{-1}\log(16/\delta)$ and $N\geq \lambda^{-2}\log(8/\delta)$, then
    \begin{equation}\label{eq:alphabd_noisy}
        \widehat{\alpha} \in \mathcal{A}_{\beta}\coloneqq \set{\alpha\in\mathbb{R}^M}{\normtemp{\alpha}_M^2\leq \beta}
    \end{equation}
    with probability at least $1-\delta$. The radius $\beta\coloneqq \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)$ of the norm bound is given by~\eqref{eq:alphabd_noisy_const}.

\label{lem:alphabd_exist}
Suppose that $\mathcal{G}_{\mathcal{H}}\coloneqq \mathcal{G}\in \mathcal{H}$. Fix $\delta\in(0,1)$, $\lambda>0$, $N\in\mathbb{N}$, and $M\in\mathbb{N}$. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ and ${\{u_n\}}\sim\nu^{\otimes N}$. Define $\alpha^{\star} \in \mathbb{R}^M$ componentwise by
\begin{equation}\label{eq:alstar_exist}
    \alpha^{\star}_m\coloneqq \alpha_{\mathcal{H}}(\theta_m)\mathds{1}_{\{\abstemp{\alpha_{\mathcal{H}}(\theta_m)}\leq T\}}\,,\quad\text{where}\quad T \coloneqq \sqrt{\lambda^{-1}\operatorname{\mathbb{E}}_{\theta\sim\mu}|\alpha_{\mathcal{H}}(\theta)|^2}
\end{equation}
and
$\mathcal{G}_{\mathcal{H}}=\operatorname{\mathbb{E}}_{\theta\sim\mu}[\alpha_{\mathcal{H}}(\theta)\varphi({\,\cdot\,};\theta)]$ with $\normtemp{\mathcal{G}_{\mathcal{H}}}_{\mathcal{H}}^2=\operatorname{\mathbb{E}}_{\theta\sim\mu}\abstemp{\alpha_{\mathcal{H}}(\theta)}^2$.
If $M \ge \lambda^{-1}\log(4/\delta)$, then with probability at least $ 1-\delta$ in the random feature parameters $\theta_1,\dots, \theta_M$, it holds that
\begin{equation}\label{eq:alphabd_exist}
    \mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}_{\mathcal{H}}) \le 81 \lambda \Vert \mathcal{G}_{\mathcal{H}} \Vert_{\mathcal{H}}^2.
\end{equation}

\label{lem:app_misspec_con}
    Let $\rho$ be as in Assumption~\ref{ass:misspec}. Fix $\delta\in(0,1)$. With probability at least $1-\delta$, it holds that
    \begin{equation}
        \frac{2}{N}\sum_{n=1}^N\normtemp{\rho(u_n)}_{\mathcal{Y}}^2 \leq 4 \operatorname{\mathbb{E}}_{u\sim\nu} \normtemp{\rho(u)}_{\mathcal{Y}}^2 + \frac{9\normtemp{\rho}_{L^\infty_\nu}^2\log(2/\delta)}{N}\,.
    \end{equation}

\label{lem:app_noise_sup_cross}
    Let Assumptions \ref{ass:rf} and \ref{ass:joint_dist_noise} hold. Fix $\alpha\in\mathbb{R}^M$, ${\{\theta_m\}}\sim\mu^{\otimes M}$, and $\delta\in(0,1)$. With probability at least $1-\delta$, it holds that
    \begin{equation}
        \frac{2}{N}\sum_{n=1}^N\iptemp{-\eta_n}{\Phi(u_n;\alpha)}_{\mathcal{Y}}\leq 16e^{3/2}\normtemp{\eta_1}_{\psi_1(\mathcal{Y})}\normtemp{\alpha}_M \sqrt{\frac{\log(2/\delta)}{N}}\,.
    \end{equation}

\label{prop:est_error_combined}
Let Assumption \ref{ass:rf} hold. Suppose $\mathcal{G}$ satisfies Assumption~\ref{ass:misspec}. Let ${\{\theta_m\}}\sim\mu^{\otimes M}$ for the RFM $\Phi$ given by \eqref{eq:rf_model}. Fix $\delta\in(0,1)$. For iid input samples ${\{u_n\}}\sim\nu^{\otimes N}$, define the random variable
    \begin{equation}
        \mathcal{E}_\beta\bigl({\{u_n\}},{\{\theta_m\}}\bigr)
        \coloneqq \sup_{\alpha\in\mathcal{A}_\beta}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\normtemp{\mathcal{G}(u_n)-\Phi(u_n;\alpha)}_{\mathcal{Y}}^2 - \operatorname{\mathbb{E}}_{u}\normtemp{\mathcal{G}(u)-\Phi(u;\alpha)}_{\mathcal{Y}}^2}\,,
    \end{equation}
    where $\mathcal{A}_\beta\coloneqq \{\alpha'\in\mathbb{R}^M\, \vert \,  \normtemp{\alpha'}_M^2\leq \beta\}$ and the deterministic radius $\beta=\beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)$ is given in \eqref{eq:alphabd_noisy_const} with $\mathcal{G}$ as above. If $N\geq \log(1/\delta)$, then with probability at least $1-\delta$ it holds that
    \begin{equation}\label{eq:app_est_bdd}
        \mathcal{E}_\beta\bigl({\{u_n\}},{\{\theta_m\}}\bigr) \leq 32e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\sqrt{\frac{6\log(2/\delta)}{N}}\,.
    \end{equation}

\label{thm:bern_vv}
Let $Z$ be an $H$-valued random variable, where $(H,\iptemp{\cdot}{\cdot},\normtemp{{\,\cdot\,}})$ is a separable Hilbert space. Suppose there exist positive numbers $b>0$ and $\sigma>0$ such that 
\begin{equation}\label{eq:bern_cond}
    \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p\leq \frac{1}{2}p!\sigma^2 b^{p-2} \quad\text{for all}\quad p\geq 2\,.
\end{equation}
For any $\delta\in(0,1)$ and $N\in\mathbb{N}$, denoting by $\{Z_n\}_{n=1}^N$ a sequence of $N$ iid copies of $Z$, it holds that
\begin{equation}\label{eq:bern_vv}
    \Pr\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\{\normtemp[\bigg]{\frac{1}{N}\sum_{n=1}^NZ_n - \operatorname{\mathbb{E}} Z}\leq \frac{2b\log(2/\delta)}{N} + \sqrt{\frac{2\sigma^2\log(2/\delta)}{N}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\}\geq 1-\delta\,.
\end{equation}

The result is a direct consequence of \citep[Cor. 1, p. 144]{pinelis1986remarks} in the iid Hilbert space setting. In this case, it holds for any $t>0$ that
\begin{equation*}
    \Pr\bigl\{\normtemp{S_N-\operatorname{\mathbb{E}} S_N}\geq t\bigr\}\leq 2\exp\biggl(-\frac{N^2t^2}{2N\sigma^2+2Nt b}\biggr)=2\exp\biggl(-\frac{Nt^2}{2\sigma^2+2bt}\biggr)\,,
\end{equation*}
where $S_n\coloneqq \frac{1}{N}\sum_{n=1}^N Z_n$. Setting the right hand side equal to $\delta$, solving a quadratic equation for $t=t(\delta)$, and using the inequality $\sqrt{a+b}\leq\sqrt{a} + \sqrt{b}$ to bound $t(\delta)$ from above leads to \eqref{eq:bern_vv}.

\label{lem:bern_vv}
    Let $Z$ be a (potentially) uncentered random variable such that
    \begin{equation}\label{eq:lem_bern_vv_bdd}
        \normtemp{Z}\leq c \ \ \text{almost surely} \ \quad\text{and}\quad \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^2\leq v^2
    \end{equation}
    for some $c>0$ and $v>0$. Then $Z$ satisfies Bernstein's moment condition~\eqref{eq:bern_cond} with $b=2c$ and $\sigma = v$. If $\operatorname{\mathbb{E}} Z=0$, then taking $b=c$ suffices.

It holds that $\normtemp{Z-\operatorname{\mathbb{E}} Z}\leq \normtemp{Z} + \operatorname{\mathbb{E}}\normtemp{Z}\leq 2c$ almost surely. We compute
\begin{align*}
    \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p &= \operatorname{\mathbb{E}}[\normtemp{Z-\operatorname{\mathbb{E}} Z}^2 \normtemp{Z-\operatorname{\mathbb{E}} Z}^{p-2}] \leq \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^2 (2c)^{p-2}\\
    &\qquad \leq v^2 (2c)^{p-2}\leq \frac{1}{2}p! v^2 (2c)^{p-2}
\end{align*}
because $1 \leq p!/2$ for all $p\geq 2$. The centered improvement is trivial.

