\label{thm:bern_vv_banach}
Let $Z$ be a $\mathcal{Z}$-valued random variable, where $(\mathcal{Z},\normtemp{{\,\cdot\,}})$ is a separable Banach space. Suppose there exist positive numbers $b>0$ and $\sigma>0$ such that 
\begin{equation}\label{eq:bern_cond_banach}
    \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p\leq \frac{1}{2}p!\sigma^2 b^{p-2} \quad\text{for all}\quad p\geq 2\,.
\end{equation}
For any $\delta\in(0,1)$ and $N\in\mathbb{N}$, denoting by $\{Z_n\}_{n=1}^N$ a sequence of $N$ iid copies of $Z$, it holds that
\begin{equation}\label{eq:bern_vv_banach}
    \Pr\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\{\normtemp[\bigg]{\frac{1}{N}\sum_{n=1}^NZ_n} - \operatorname{\mathbb{E}} \normtemp[\bigg]{\frac{1}{N}\sum_{n=1}^NZ_n}\leq \frac{2b\log(1/\delta)}{N} + \sqrt{\frac{2\sigma^2\log(1/\delta)}{N}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\}\geq 1-\delta\,.
\end{equation}

\label{prop:app_subexp_bern_mom}
    Let $Z$ be a $(\mathcal{Z},\normtemp{{\,\cdot\,}})$-valued subexponential random variable, that is, $\normtemp{Z}_{\psi_1(\mathcal{Z})}<\infty$. Then $Z$ satisfies
    \begin{equation}
        \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p\leq \frac{1}{2}p!\sigma^2 b^{p-2} \quad\text{for all}\quad p\geq 2\,,
    \end{equation}
    where
    \begin{equation}\label{eq:prop_app_subexp_bern_mom}
        \sigma^2 \coloneqq 4e\sqrt{\operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^2}\normtemp{Z}_{\psi_1(\mathcal{Z})}\quad\text{and}\quad b\coloneqq 4e\normtemp{Z}_{\psi_1(\mathcal{Z})}\,.
    \end{equation}

By the Cauchy--Schwarz inequality,
\begin{equation*}
      \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p=\operatorname{\mathbb{E}}[\normtemp{Z-\operatorname{\mathbb{E}} Z}\normtemp{Z-\operatorname{\mathbb{E}} Z}^{p-1}]
    \leq \normtemp{Z-\operatorname{\mathbb{E}} Z}_{L^2_{\mathbb{P}}}(\operatorname{\mathbb{E}} \normtemp{Z-\operatorname{\mathbb{E}} Z}^{2p-2})^{1/2}\,.
\end{equation*}
The inequality $\abstemp{a+b}^q\leq 2^{q-1}(\abstemp{a}^q +\abstemp{b}^q)$, Jensen's inequality, and $\normtemp{Z}_{\psi_1(\mathcal{Z})}<\infty$ show that
\begin{equation*}
    \operatorname{\mathbb{E}} \normtemp{Z-\operatorname{\mathbb{E}} Z}^{2p-2}\leq 2^{2p-2}\operatorname{\mathbb{E}}\normtemp{Z}^{2p-2}\leq 2^{2p-2}(2p-2)^{2p-2}\normtemp{Z}_{\psi_1(\mathcal{Z})}^{2p-2}\,.
\end{equation*}
Next, Stirling's approximation $(q/e)^q\leq q!$ and $q!=q(q-1)!\geq 2(q-1)!$ for $q\geq 2$ yields
\begin{align*}
    \operatorname{\mathbb{E}}\normtemp{Z-\operatorname{\mathbb{E}} Z}^p&\leq 2^{2p-2}\normtemp{Z-\operatorname{\mathbb{E}} Z}_{L^2_{\mathbb{P}}}(p-1)^{p-1}\normtemp{Z}_{\psi_1(\mathcal{Z})}^{p-1}\\
    &\leq (p!/2)\normtemp{Z-\operatorname{\mathbb{E}} Z}_{L^2_{\mathbb{P}}}2^{2p-2} e^{p-1} \normtemp{Z}_{\psi_1(\mathcal{Z})}^{p-1}\,.
\end{align*}
Rearranging the exponents to fit the Bernstein moment condition form completes the proof.

