\label{lem:rkhs_approx_soln}
    There exists a unique solution $\mathcal{G}_\vartheta$ to \eqref{eq:rkhs_approx} given by
    \begin{equation}\label{eq:rkhs_approx_soln}
        \mathcal{G}_\vartheta = (\iota^*\iota + \vartheta \mathrm{Id})^{-1}\iota^*\mathcal{G}\,.
    \end{equation}

\label{lem:converge_rkhs}
    Suppose that $\mathcal{G}$ is in the $L^2_\nu$-closure of $\mathcal{H}$. Under the prevailing assumptions of this section,
    \begin{equation}\label{eq:scrA_to_zero}
        \lim_{\vartheta\to 0}\mathscr{A}_{\mathcal{G}}(\vartheta)=0\,.
    \end{equation}

By Lem.~\ref{lem:rkhs_approx_soln} and the Woodbury identity~\cite[Thm. 1]{ogawa1988operator}, it holds that
\begin{equation*}
    \iota\mathcal{G}_\vartheta = \iota(\iota^*\iota^{\phantom{*}} + \vartheta \mathrm{Id}_{\mathcal{H}})^{-1}\iota^*\mathcal{G} = \mathcal{K}(\mathcal{K}+\vartheta\mathrm{Id}_{L^2_\nu})^{-1}\mathcal{G} = (\mathcal{K}+\vartheta\mathrm{Id}_{L^2_\nu})^{-1} \mathcal{K}\mathcal{G}\,.
\end{equation*}
The second equality holds by simultaneous diagonalization. Writing $\mathcal{G}$ in the eigenbasis of $\mathcal{K}$ yields
\begin{equation*}
    \mathcal{G} - \iota\mathcal{G}_\vartheta = \big[\mathrm{Id}_{L^2_\nu} - (\mathcal{K}+\vartheta\mathrm{Id}_{L^2_\nu})^{-1} \mathcal{K}\big]\mathcal{G}=\sum_{j\in\mathbb{N}}\frac{\vartheta}{\lambda_j + \vartheta} \iptemp{e_j}{\mathcal{G}}_{L^2_\nu}\, e_j\,. 
\end{equation*}
Similarly, using the norm isometry between $L^2_\nu$ and the RKHS \cite[see, e.g.,][pp. 403--404]{carmeli2006vector} we obtain
\begin{equation*}
    \normtemp{\mathcal{G}_\vartheta}_{\mathcal{H}}^2
    =\normtemp{\mathcal{K}^{-1/2}\iota \mathcal{G}_\vartheta}_{L^2_\nu}^2
    =\normtemp{\mathcal{K}^{1/2}(\mathcal{K}+\vartheta\mathrm{Id}_{L^2_\nu})^{-1}\mathcal{G}}_{L^2_\nu}^2
   =\sum_{j\in\mathbb{N}}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{\sqrt{\lambda_j}}{\lambda_j+\vartheta}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)^2\iptemp{e_j}{\mathcal{G}}_{L^2_\nu}^2\,.
\end{equation*}
Since the infimum in \eqref{eq:scrA_rkhs} is attained at $\mathcal{G}_\vartheta$~\eqref{eq:rkhs_approx}, we deduce that
\begin{align*}
    \mathscr{A}_{\mathcal{G}}(\vartheta)&=\normtemp{\mathcal{G} - \iota \mathcal{G}_\vartheta}_{L^2_\nu}^2 + \vartheta \normtemp{\mathcal{G}_\vartheta}_{\mathcal{H}}^2\\
    &=\sum_{j\in\mathbb{N}}\frac{\vartheta^2}{(\lambda_j + \vartheta)^2} \iptemp{e_j}{\mathcal{G}}_{L^2_\nu}^2 + \sum_{j\in\mathbb{N}}\frac{\vartheta\lambda_j}{(\lambda_j + \vartheta)^2}\iptemp{e_j}{\mathcal{G}}_{L^2_\nu}^2\\
    &=\sum_{j\in\mathbb{N}}\Bigl(\frac{\vartheta}{\lambda_j + \vartheta}\Bigr)\iptemp{e_j}{\mathcal{G}}_{L^2_\nu}^2\,.
\end{align*}
Using $\vartheta/(\lambda_j+\vartheta)\leq 1$ for each $j\in\mathbb{N}$ and $\mathcal{G}\in \overline{\mathcal{H}}^{L^2_\nu}$ (the $L^2_\nu$-closure of $\mathcal{H}$), it follows that
\begin{equation}
    \mathscr{A}_{\mathcal{G}}(\vartheta) = \sum_{\{j\in\mathbb{N} \,|\, \lambda_j\neq 0\}}\Bigl(\frac{\vartheta}{\lambda_j + \vartheta}\Bigr)\iptemp{e_j}{\mathcal{G}}_{L^2_\nu}^2 \to 0 \quad\text{as}\quad \vartheta\to 0
\end{equation}
by dominated convergence.

\label{lem:rkhs_approx_rate}
    Suppose $\mathcal{G}\in\mathrm{Im}(\mathcal{K}^{r/2})$ for some $r\geq 0$. Then for any $\vartheta>0$, it holds under the prevailing assumptions of this section that
    \begin{equation}
    \mathscr{A}_{\mathcal{G}}(\vartheta)
    \leq 
    \normtemp{\mathcal{K}^{-r/2}\mathcal{G}}^2_{L^2_{\nu}(\mathcal{X};\mathcal{Y})}\times
    \begin{cases}
        \vartheta^{r},\quad &\text{if }\ r\in[0,1]\,,\\
        \vartheta\normtemp{\mathcal{K}}_{\mathcal{L}(L^2_\nu)}^{r-1},\quad &\text{if }\ r>1\,.
    \end{cases}
    \end{equation}

The proof closely follows the argument of~\citet[Thm. 4, p. 295]{smale2005shannon}. By hypothesis, there exists $F_{\mathcal{G}}\in L^2_\nu(\mathcal{X};\mathcal{Y})$ such that $\mathcal{G} = \mathcal{K}^{r/2}F_{\mathcal{G}}$. Then
\begin{equation*}
 \mathscr{A}_{\mathcal{G}}(\vartheta) = \sum_{j\in\mathbb{N}}\frac{\vartheta\lambda_j^r}{\lambda_j + \vartheta} \iptemp{e_j}{F_{\mathcal{G}}}_{L^2_\nu}^2
 \leq
 \biggl(\sup_{j\in\mathbb{N}} \frac{\vartheta\lambda_j^r}{\lambda_j + \vartheta}\biggr)\normtemp{F_{\mathcal{G}}}_{L^2_\nu}^2\,.
\end{equation*}
For any $j\in\mathbb{N}$, the argument of the supremum equals
\begin{equation*}
\frac{\vartheta\lambda_j^r}{\lambda_j + \vartheta}=\Bigl(\frac{\lambda_j}{\lambda_j + \vartheta}\Bigr)\Bigl(\frac{\lambda_j}{\lambda_j + \vartheta}\Bigr)^{r-1}
\frac{\vartheta}{(\lambda_j + \vartheta)^{1-r}}= \vartheta^r \Bigl(\frac{\lambda_j}{\lambda_j + \vartheta}\Bigr)^r\Bigl(\frac{\vartheta}{\lambda_j + \vartheta}\Bigr)^{1-r}.
\end{equation*}
This is bounded above by $\vartheta^r$ for all $j\in\mathbb{N}$ if $r\geq0$ and $r\leq 1$. Otherwise, $r>1$ and
\begin{equation*}
    \frac{\vartheta\lambda_j^r}{\lambda_j + \vartheta}=\vartheta \lambda_j^{r-1}\Bigl(\frac{\lambda_j}{\lambda_j + \vartheta}\Bigr)\leq \vartheta \lambda_j^{r-1}\,.
\end{equation*}
Taking the supremum over $j\in\mathbb{N}$ completes the proof.

Under the hypotheses, \eqref{eq:alphabd_noisy_risk} in Prop.~\ref{prop:train_erm_bound_noisy} holds with probability at least $1-\delta$ provided that $M\geq \lambda^{-1}\log(16/\delta)$ and $N\geq \lambda^{-2}\log(8/\delta)$. That is, $\mathscr{R}_N(\widehat{\alpha};\mathcal{G})\leq \mathscr{R}^{\lambda}_N(\widehat{\alpha};\mathcal{G})\leq \beta\lambda$, where $\beta=\beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)$ is given by \eqref{eq:alphabd_noisy_const}. In particular, $\widehat{\alpha}\in \mathcal{A}_\beta$~\eqref{eq:alphabd_noisy} on the same event (by Cor.~\ref{cor:train_norm_bound_noisy}). It follows that, on this event, 
\begin{equation*}
    \mathscr{R}(\widehat{\alpha};\mathcal{G})-\mathscr{R}_N(\widehat{\alpha};\mathcal{G})\leq \sup_{\alpha\in\mathcal{A}_\beta}\abstemp[\big]{\mathscr{R}_N(\alpha;\mathcal{G}) - \mathscr{R}(\alpha;\mathcal{G})}\,.
\end{equation*}
Application of Prop.~\ref{prop:est_error_combined} shows that the right hand side of the above display is bounded above by
\begin{equation*}
    32\sqrt{6}e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\lambda\leq 79e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 \beta(\rho,\lambda,\mathcal{G}_{\mathcal{H}},\eta)\bigr)\lambda
\end{equation*}
with probability at least $1-\delta$ because $N\geq\lambda^{-2}\log(8/\delta)\geq \log(2/\delta)$. Recalling \eqref{eq:proof_decomp}, using $1\leq 79e^{3/2}$, and applying a union bound completes the proof.

For $k\in\mathbb{N}$ and $\delta\in (0,1)$, the trained RFM satisfies $\normtemp{\mathcal{G} - \Phi({\,\cdot\,};\widehat{\alpha}^{(k)})}_{L^2_\nu}\leq c s_k$ for some deterministic constant $c>0$, where the sequence $s_n\to 0$ as $n\to\infty$ is given by the right hand side of \eqref{eq:main_consis_inf} with $\lambda=\lambda_n$ for each $n\in\mathbb{N}$ (by Lem.~\ref{lem:converge_rkhs}). This inequality holds with probability at least $1-\delta$ if $M\gtrsim \lambda_k^{-1}\log(2/\delta)$ and $N\gtrsim \lambda_k^{-2}\log(2/\delta)$ by Thm.~\ref{thm:error_bound_total_G}. Now choose $\delta = \lambda_k$. Then
\begin{equation*}
    \sum_{k\in\mathbb{N}}\Pr\bigl\{ \normtemp{\mathcal{G} - \Phi({\,\cdot\,};\widehat{\alpha}^{(k)})}_{L^2_\nu} > c s_k \bigr\}\leq \sum_{k\in\mathbb{N}}\lambda_k<\infty\,.
\end{equation*}
The first Borel--Cantelli lemma establishes that there exists an $\mathbb{N}$-valued random variable $k_0$ such that $\normtemp{\mathcal{G} - \Phi({\,\cdot\,};\widehat{\alpha}^{(k)})}_{L^2_\nu}\leq cs_k$ for all $k>k_0$ almost surely. This implies the desired result.

