 \frac{1}{M} \sum_{m=1}^M Z_m - \operatorname{\mathbb{E}} Z
 \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\Vert^2_{L^2_{\nu_N}}
\le
 \frac{32 T^2 \Vert \varphi \Vert_{L^\infty}^2 \log^2(2/\delta)}{M^2} + \frac{4\Vert \varphi \Vert_{L^\infty}^2\log(2/\delta) \operatorname{\mathbb{E}}_\theta |\alpha(\theta)|^2}{M}\,.
\end{equation}

By boundedness of $|\alpha_{\le T}|\le T$, we have the trivial uniform upper bound $\Vert Z_m \Vert_{L^2_{\nu_N}} \le T\Vert \varphi \Vert_{L^\infty}$ for each $m$. The variance is bounded above as
\begin{equation*}
    \sigma^2 \coloneqq \operatorname{\mathbb{E}} \Vert Z - \operatorname{\mathbb{E}} Z \Vert_{L^2_{\nu_N}}^2
\le
\operatorname{\mathbb{E}} \Vert Z \Vert_{L^2_{\nu_N}}^2
\le
\Vert \varphi \Vert_{L^\infty}^2 \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2\,.
\end{equation*}
By Lem.~\ref{lem:bern_vv} and Thm.~\ref{thm:bern_vv}, it holds with probability at least $1-\delta$ that
\begin{equation*}
    \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\Vert \frac{1}M \sum_{m=1}^M Z_m - \operatorname{\mathbb{E}} Z \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right \Vert_{L^2_{\nu_N}} 
\le 
\frac{4T\Vert \varphi \Vert_{L^\infty} \log(2/\delta)}{M} + \sqrt{\frac{2\sigma^2 \log(2/\delta)}{M}}\,.
\end{equation*}
Squaring both sides and substitution of the above bound on $\sigma^2$ yields the claimed estimate.

\label{lem:3}
Let $\alpha\in L^2_\mu(\Theta;\mathbb{R})$ and ${\{\theta_m\}}\sim\mu^{\otimes M}$. With probability at least $1-\delta$, it holds that
\begin{equation}
    \frac{1}{M} \sum_{m=1}^M |\alpha_{\le T}(\theta_m)|^2 
    \le 
    \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2 + \frac{4T^2 \log(2/\delta)}{M} + \sqrt{\frac{2T^2 \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2 \log(2/\delta)}{M}}\,.
\end{equation}

We apply Bernstein's inequality~\eqref{eq:bern_vv} to the random variable $Z(\theta) \coloneqq |\alpha_{\le T}(\theta)|^2$ with $\theta\sim \mu$ and $M\in\mathbb{N}$ iid copies $Z_1,\dots, Z_M$ of $Z$ defined by $Z_m = Z(\theta_m)$ for each $m$. We note that $|Z|\le T^2$ by definition. The variance of $Z$ satisfies the upper bound
\begin{equation*}
    \sigma^2\coloneqq \operatorname{\mathbb{E}}\abstemp{Z-\operatorname{\mathbb{E}} Z}^2
\le \operatorname{\mathbb{E}}\abstemp{Z}^2 
=\operatorname{\mathbb{E}}_\theta|\alpha_{\le T}(\theta)|^4
\le T^2 \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2\,.
\end{equation*}
It follows from Lem.~\ref{lem:bern_vv} and Thm.~\ref{thm:bern_vv} that
\begin{equation*}
    \frac{1}{m} \sum_{m=1}^M Z_m 
\le 
\operatorname{\mathbb{E}} Z + \frac{4T^2 \log(2/\delta)}{M} + \sqrt{\frac{2\sigma^2 \log(2/\delta)}{M}}
\end{equation*}
with probability at least $1-\delta$. This in turn implies that
\begin{equation*}
    \frac{1}{M} \sum_{m=1}^M |\alpha_{\le T}(\theta_m)|^2 
\le 
\operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2] + \frac{4T^2 \log(2/\delta)}{M} + \sqrt{\frac{2T^2 \operatorname{\mathbb{E}}|\alpha(\theta)|^2 \log(2/\delta)}{M}}
\end{equation*}
with at least the same probability. This is the claim.

Write $T\coloneqq T(\lambda)$ and $\alpha\coloneqq\alpha_{\mathcal{H}}$. Next, define $\alpha_{\le T}\in L^2_\mu(\Theta;\mathbb{R})$ by
\begin{equation*}
    \theta\mapsto \alpha_{\le T}(\theta)\coloneqq \alpha(\theta)\mathds{1}_{\{\abstemp{\alpha(\theta)}\leq T\}}  = 
    \begin{cases}
    \alpha(\theta), & \text{if }|\alpha(\theta)| \le T\,, \\
    0, & \text{otherwise}\,.
    \end{cases}
\end{equation*}
We define $\alpha_{>T}\coloneqq \alpha\mathds{1}_{\{\abstemp{\alpha}>T\}}$ similarly, so that $\alpha \equiv \alpha_{\le T} + \alpha_{>T}$ holds true. Then for $\theta_1,\dots, \theta_M$, we have $\alpha^{\star} \in \mathbb{R}^M$ given by $\alpha^{\star}_m=\alpha_{\le T}(\theta_m)$ for each $m\in\{1,\ldots, M\}$. 
We claim that $\mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}) \le (74 \Vert \varphi \Vert_{L^\infty}^2 + 7)\lambda \operatorname{\mathbb{E}}_\theta|\alpha_{\mathcal{H}}(\theta)|^2$ with high probability, which implies the asserted bound \eqref{eq:alphabd_exist}. To see this, we make the error decomposition
\begin{align}
\mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}) 
&=
\frac{1}{N} \sum_{n=1}^N \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\Vert
 \mathcal{G}(u_n) - \frac{1}{M} \sum_{m=1}^M \alpha_{\le T}(\theta_m) \varphi(u_n;\theta_m)
 \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\Vert^2_{\mathcal{Y}}
 +
 \frac{\lambda}{M} \sum_{m=1}^M |\alpha_{\le T}(\theta_m)|^2
 \\
&\le
\frac{2}{N} \sum_{n=1}^N \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\Vert
 \mathcal{G}(u_n) - \operatorname{\mathbb{E}}_\theta\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[ \alpha_{\le T}(\theta) \varphi(u_n;\theta) \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]
 \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\Vert^2_{\mathcal{Y}}\tag{I}\label{eq:alphabd_1}
 \\
 &\qquad
 + \frac{2}{N} \sum_{n=1}^N \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left\Vert
 \frac{1}{M} \sum_{m=1}^M \alpha_{\le T}(\theta_m) \varphi(u_n;\theta_m) - \operatorname{\mathbb{E}}_\theta\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[ \alpha_{\le T}(\theta) \varphi(u_n;\theta) \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]
 \aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right\Vert^2_{\mathcal{Y}}\tag{II}\label{eq:alphabd_2}
 \\
 &\qquad\qquad
 + \frac{\lambda}{M} \sum_{m=1}^M |\alpha_{\le T}(\theta_m)|^2\,.
 \tag{III}\label{eq:alphabd_3}
\end{align}
Each of the three terms \eqref{eq:alphabd_1}--\eqref{eq:alphabd_3} is estimated as follows.

By Lem.~\ref{lem:1}, we can bound
\begin{equation*}
    \eqref{eq:alphabd_1}
\le \frac{2\Vert \varphi \Vert_{L^\infty}^2 (\operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2)^2}{T^2}
= 2 \lambda \Vert \varphi \Vert_{L^\infty}^2 \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2\,.
\end{equation*}

Lem.~\ref{lem:2} delivers the bound
\begin{align*}
\eqref{eq:alphabd_2}
&\le  \frac{64 T^2 \Vert \varphi \Vert_{L^\infty}^2 \log(2/\delta)^2}{M^2} + \frac{8\Vert \varphi \Vert_{L^\infty}^2\log(2/\delta) \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2}{M}
\\
&= 
\lambda \operatorname{\mathbb{E}}_\theta|\alpha(\theta)|^2
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(
\frac{64 \Vert \varphi \Vert_{L^\infty}^2 \log(2/\delta)^2}{\lambda^2 M^2} + \frac{8\Vert \varphi \Vert_{L^\infty}^2\log(2/\delta) }{\lambda M}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)
\end{align*}
with probability at least $ 1-\delta$.

Last, Lem.~\ref{lem:3} yields
\begin{align*}
\eqref{eq:alphabd_3}
&\le
\lambda \operatorname{\mathbb{E}}|\alpha(\theta)|^2
+ \frac{4\lambda T^2 \log(2/\delta)}{M} + \lambda\sqrt{\frac{2T^2 \operatorname{\mathbb{E}}|\alpha(\theta)|^2\log(2/\delta)}{M}}
\\
&=
\lambda \operatorname{\mathbb{E}}_\theta |\alpha(\theta)|^2 
\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(
1 + \frac{4\log(2/\delta)}{\lambda M} + \sqrt{\frac{2\log(2/\delta)}{\lambda M}}
\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)
\end{align*}
with probability at least $ 1-\delta$.

Combining the three estimates, it follows that if 
\begin{equation*}
    \frac{\log(2/\delta)}{\lambda M} \le 1\,,
\end{equation*}
then
\begin{equation*}
    \mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}_{\mathcal{H}})=\mathscr{R}_N^\lambda(\alpha^{\star};\mathcal{G}) \le  (74 \Vert \varphi \Vert_{L^\infty}^2 + 7) \lambda\operatorname{\mathbb{E}}_\theta|\alpha_{\mathcal{H}}(\theta)|^2
\end{equation*}
with probability at least $ 1-2\delta$. We used the fact that $\sqrt{2}\leq 2$. This is the claimed upper bound.

Define $Z_n(\alpha)\coloneqq \iptemp{-\eta_n}{\Phi(u_n;\alpha)}_{\mathcal{Y}}$ for each $n$. Conditioned on ${\{\theta_m\}}$, it holds that $Z_n$ is an iid copy of $Z_1$. By the assumption $\operatorname{\mathbb{E}}[\eta_1 \, \vert \, u_1] = 0$, we have
\begin{align}
\begin{aligned}
\label{eq:Z1eq}
\operatorname{\mathbb{E}} Z_1(\alpha) 
&= \operatorname{\mathbb{E}}_{(u_1,\eta_1)}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[\iptemp{-\eta_1}{\Phi(u_1;\alpha)}_{\mathcal{Y}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]
    \\
&=\operatorname{\mathbb{E}}_{u_1\sim \nu}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[\operatorname{\mathbb{E}}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[\iptemp{-\eta_1}{\Phi(u_1;\alpha)}_{\mathcal{Y}}\, \vert \, u_1\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]
\\
&=\operatorname{\mathbb{E}}_{u_1\sim \nu}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left[\iptemp{-\operatorname{\mathbb{E}}[\eta_1\, \vert \, u_1]}{\Phi(u_1;\alpha)}_{\mathcal{Y}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right]
\\
&=0\,.
\end{aligned}
\end{align}

Next,
\begin{equation*}
    \abstemp{Z_1(\alpha)}\leq \normtemp{\eta_1}_{\mathcal{Y}}\normtemp{\Phi(u_1;\alpha)}_{\mathcal{Y}}\leq \normtemp{\eta_1}_{\mathcal{Y}}\normtemp{\alpha}_M\normtemp{\varphi}_{L^\infty}
\end{equation*}
by two applications of the Cauchy--Schwarz inequality, one in $\mathcal{Y}$ and the other in $\mathbb{R}^M$. We deduce that $\normtemp{Z_1(\alpha)}_{\psi_1}\leq \normtemp{\eta_1}_{\psi_1(\mathcal{Y})}\normtemp{\alpha}_M\normtemp{\varphi}_{L^\infty}$, conditioned on ${\{\theta_m\}}$. Prop.~\ref{prop:app_subexp_bern_mom}, Thm.~\ref{thm:bern_vv} (Bernstein's inequality), and a similar argument to that in the proof of Cor.~\ref{cor:app_subexp_norm} deliver the asserted bound.

\label{lem:app_noise_sup_con}
    Fix $t>0$ and $\delta\in(0,1)$. Define
    \begin{equation}
        Z_t\coloneqq \sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\iptemp{\eta_n}{\Phi(u_n;\alpha)}_{\mathcal{Y}}}\,,\quad\text{where}\quad \mathcal{A}_t\coloneqq \set{\alpha\in\mathbb{R}^M}{\normtemp{\alpha}_M^2\leq t}\,.
    \end{equation}
    If $N\geq\log(1/\delta)$, then conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$ it holds that
    \begin{equation}
        Z_t\leq \operatorname{\mathbb{E}}_{\{(u_n,\eta_n)\}} [Z_t] + 8e^{3/2}\normtemp{\eta_1}_{\psi_1(\mathcal{Y})}\normtemp{\varphi}_{L^\infty}\sqrt{\frac{\log(1/\delta)}{N}}\sqrt{t}
    \end{equation}
    with probability at least $1-\delta$.

For any $\alpha\in\mathcal{A}_t$, we compute
\begin{align*}
    \abstemp{\iptemp{\eta_1}{\Phi(u_1;\alpha)}_{\mathcal{Y}}}&=\abstemp[\bigg]{\frac{1}{M}\sum_{m=1}^M\alpha_m\iptemp{\eta_1}{\varphi(u_1;\theta_m)}_{\mathcal{Y}}}\\
    &\leq \biggl(\frac{1}{M}\sum_{m=1}^M\abstemp{\alpha_m}^2\biggr)^{1/2}\biggl(\frac{1}{M}\sum_{m=1}^M\iptemp{\eta_1}{\varphi(u_1;\theta_m)}^2_{\mathcal{Y}}\biggr)^{1/2}\\
    &\leq \sqrt{t}\biggl(\normtemp{\eta_1}_{\mathcal{Y}}^2\frac{1}{M}\sum_{m=1}^M\normtemp{\varphi(u_1;\theta_m)}^2_{\mathcal{Y}}\biggr)^{1/2}\, .
\end{align*}
We used the Cauchy--Schwarz inequality twice. By the boundedness of $\varphi$, the above display gives
\begin{equation*}
        \normtemp[\big]{\iptemp{\eta_1}{\Phi(u_1;{\,\cdot\,})}}_{\psi_1(C(\mathcal{A}_t;\mathbb{R}))}=\normtemp[\Big]{\sup_{\alpha\in\mathcal{A}_t}\abstemp[\big]{\iptemp{\eta_1}{\Phi(u_1;\alpha)}_{\mathcal{Y}}}}_{\psi_1}\leq \normtemp{\eta_1}_{\psi_1(\mathcal{Y})}\normtemp{\varphi}_{L^\infty}\sqrt{t}\, .
\end{equation*}
The iid random variables $\iptemp{\eta_n}{\Phi(u_n;{\,\cdot\,})}_{\mathcal{Y}}\colon \alpha\mapsto \iptemp{\eta_n}{\Phi(u_n;\alpha)}_{\mathcal{Y}}$ (conditional on ${\{\theta_m\}}$) are linear and hence continuous. Application of \eqref{eq:app_subexp_norm_simple} in Cor.~\ref{cor:app_subexp_norm} to $\iptemp{\eta_n}{\Phi(u_n;{\,\cdot\,})}_{\mathcal{Y}}$ taking value in the separable Banach space $C(\mathcal{A}_t;\mathbb{R})$ of continuous functions from compact set $\mathcal{A}_t\subset\mathbb{R}^M$ into $\mathbb{R}$, equipped with the supremum norm, completes the proof.

\label{lem:app_noise_sup_expect}
    Fix $t>0$. Define $\mathcal{A}_t$ as in Lem.~\ref{lem:app_noise_sup_con}. Then
    \begin{equation}\label{eq:app_noise_sup_expect}
        \operatorname{\mathbb{E}}_{\{(u_n,\eta_n)\}} \sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\iptemp{\eta_n}{\Phi(u_n;\alpha)}_{\mathcal{Y}}} \leq \frac{\normtemp{\eta_1}_{L^2_{\mathbb{P}}(\Omega;\mathcal{Y})}\normtemp{\varphi}_{L^\infty}}{\sqrt{N}}\sqrt{t}\,.
    \end{equation}

\label{lem:app_loss_sup_con}
    Fix $t>0$ and $\delta\in(0,1)$. Define
    \begin{align}
        Z_t&\coloneqq \sup_{\alpha\in\mathcal{A}_t}\abstemp[\big]{\mathscr{R}_N(\alpha;\mathcal{G})-\mathscr{R}(\alpha;\mathcal{G})}\\
        &= \sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\normtemp{\mathcal{G}(u_n)-\Phi(u_n;\alpha)}_{\mathcal{Y}}^2 - \operatorname{\mathbb{E}}_{u\sim\nu}\normtemp{\mathcal{G}(u)-\Phi(u;\alpha)}_{\mathcal{Y}}^2}\,,
    \end{align}
    where
    \begin{equation}
        \mathcal{A}_t\coloneqq \set{\alpha\in\mathbb{R}^M}{\normtemp{\alpha}_M^2\leq t}\,.
    \end{equation}
    If $N\geq\log(1/\delta)$, then conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$, it holds that
    \begin{equation}
        Z_t\leq \operatorname{\mathbb{E}}_{{\{u_n\}}} [Z_t] + 32e^{3/2}(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 t)\sqrt{\frac{\log(1/\delta)}{N}}
    \end{equation}
    with probability at least $1-\delta$.

\label{lem:app_loss_sup_expect}
    Fix $t>0$. Define $Z_t$ as in Lem.~\ref{lem:app_loss_sup_con}. Conditioned on the realizations ${\{\theta_m\}}$ in the family $\Phi$, it holds that
    \begin{equation}
        \operatorname{\mathbb{E}}_{{\{u_n\}}} [Z_t] \leq \frac{4\normtemp{\mathcal{G}}_{L_\nu^\infty}^2}{\sqrt{N}}
        + \frac{4\normtemp{\varphi}_{L^\infty}^2}{\sqrt{N}}t\,.
    \end{equation}

By Gin\'e--Zinn symmetrization \cite[see, e.g.,][Sect. 4.2, Prop. 4.11, pp. 107--108]{wainwright2019high},
\begin{equation*}
        \operatorname{\mathbb{E}}_{{\{u_n\}}} [Z_t] \leq 2\operatorname{\mathbb{E}}\sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\normtemp{\mathcal{G}(u_n)-\Phi(u_n;\alpha)}_{\mathcal{Y}}^2},\quad\text{where}\quad \varepsilon_n\stackrel{\mathrm{iid}}{\sim} \mathrm{Unif}\bigl(\{+1,-1\}\bigr)\,,
\end{equation*}
because the original summands (conditioned on ${\{\theta_m\}}$) are independent. The expectation on the right is interpreted as the conditional expectation given ${\{\theta_m\}}$ (i.e., $\operatorname{\mathbb{E}}_{{\{u_n\}},\{\varepsilon_n\}}$ over the data and Rademacher variables only). The right hand side is the Rademacher complexity of the RF model class composed with the square loss. Expanding the square, it is bounded above by
\begin{align}
    &2\operatorname{\mathbb{E}}_{{\{u_n\}},\{\varepsilon_n\}}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\normtemp{\mathcal{G}(u_n)}_{\mathcal{Y}}^2}\tag{I}\label{eq:app_loss_sup_1}\\
    &\qquad+4\operatorname{\mathbb{E}}_{{\{u_n\}},\{\varepsilon_n\}}\sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\iptemp{\mathcal{G}(u_n)}{\Phi(u_n;\alpha)}_{\mathcal{Y}}}\tag{II}\label{eq:app_loss_sup_2}\\
    &\qquad\qquad \ + 2\operatorname{\mathbb{E}}_{{\{u_n\}},\{\varepsilon_n\}}\sup_{\alpha\in\mathcal{A}_t}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\normtemp{\Phi(u_n;\alpha)}_{\mathcal{Y}}^2}\tag{III}\label{eq:app_loss_sup_3}\,.
\end{align}
We now estimate each term. The first term \eqref{eq:app_loss_sup_1} satisfies the standard Monte Carlo bound
\begin{equation*}
        \eqref{eq:app_loss_sup_1}\leq 2\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\operatorname{\mathbb{E}}\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\normtemp{\mathcal{G}(u_n)}_{\mathcal{Y}}^2}^2\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)^{1/2}=
\frac{2}{\sqrt{N}}\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{1}{N}\sum_{n=1}^N\operatorname{\mathbb{E}}\normtemp{\mathcal{G}(u_n)}_{\mathcal{Y}}^4\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)^{1/2}\leq \frac{2\normtemp{\mathcal{G}}_{L^\infty_\nu}^2}{\sqrt{N}}\,.
\end{equation*}
For the second term \eqref{eq:app_loss_sup_2}, we begin by estimating the empirical average on the set $\mathcal{A}_t$ as
\begin{align*}
    \abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\iptemp{\mathcal{G}(u_n)}{\Phi(u_n;\alpha)}_{\mathcal{Y}}} &= \abstemp[\bigg]{\frac{1}{M}\sum_{m=1}^M\alpha_m\biggl(\frac{1}{N}\sum_{n=1}^N \varepsilon_n\iptemp{\mathcal{G}(u_n)}{\varphi(u_n;\theta_m)}_{\mathcal{Y}}\biggr)}\\
    &\leq \sqrt{t}\biggl(\frac{1}{M}\sum_{m=1}^M\abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\iptemp{\mathcal{G}(u_n)}{\varphi(u_n;\theta_m)}_{\mathcal{Y}}}^2\biggr)^{1/2}
\end{align*}
by the Cauchy--Schwarz inequality in $\mathbb{R}^M$. We deduce by Jensen's inequality and independence that
\begin{align*}
     \eqref{eq:app_loss_sup_2}&\leq\frac{4\sqrt{t}}{N}\biggl(\frac{1}{M}\sum_{m=1}^M\sum_{n,n'=1}^N\operatorname{\mathbb{E}}[\varepsilon_n\varepsilon_{n'}]\operatorname{\mathbb{E}}_{{\{u_n\}}}\bigl[\iptemp{\mathcal{G}(u_n)}{\varphi(u_n;\theta_m)}_{\mathcal{Y}}\iptemp{\mathcal{G}(u_{n'})}{\varphi(u_{n'};\theta_m)}_{\mathcal{Y}}\bigr]\biggr)^{1/2}\\
     &=\frac{4\sqrt{t}}{N}\biggl(\frac{1}{M}\sum_{m=1}^M\sum_{n=1}^N\operatorname{\mathbb{E}}_{u\sim\nu}\iptemp{\mathcal{G}(u)}{\varphi(u;\theta_m)}_{\mathcal{Y}}^2\biggr)^{1/2}.
\end{align*}
A final application of the Cauchy--Schwarz inequality in $\mathcal{Y}$ in the last line shows that the second term \eqref{eq:app_loss_sup_2} is bounded above by $4\sqrt{t}\normtemp{\mathcal{G}}_{L^\infty_\nu}\normtemp{\varphi}_{L^\infty}/\sqrt{N}$.
By Young's inequality $ab\leq a^2/2 + b^2/2$, we further bound
\begin{equation*}
    \frac{4\normtemp{\mathcal{G}}_{L^\infty_\nu}\normtemp{\varphi}_{L^\infty}\sqrt{t}}{\sqrt{N}} = \mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{2\normtemp{\mathcal{G}}_{L_\nu^\infty}}{N^{1/4}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\mathopen{}\mathclose\bgroup\left(\frac{2\normtemp{\varphi}_{L^\infty}\sqrt{t}}{N^{1/4}}\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\aftergroup\egroup\right)
\leq  \frac{2\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 }{\sqrt{N}} + \frac{2\normtemp{\varphi}_{L^\infty}^2 t}{\sqrt{N}}\,.
\end{equation*}

The third term \eqref{eq:app_loss_sup_3} is estimated in a similar manner. Expanding the empirical average on $\mathcal{A}_t$ yields
\begin{align*}
    \abstemp[\bigg]{\frac{1}{N}\sum_{n=1}^N\varepsilon_n\normtemp{\Phi(u_n;\alpha)}_{\mathcal{Y}}^2}&=\abstemp[\bigg]{\frac{1}{M}\sum_{m=1}^M\alpha_m\biggl(\frac{1}{M}\sum_{m'=1}^M\alpha_{m'}\beta_{m,m'}^{(N)}\biggr)},\quad\text{where}\quad \\
    \beta_{m,m'}^{(N)}&=\frac{1}{N}\sum_{n=1}^N\varepsilon_n\iptemp{\varphi(u_n;\theta_m)}{\varphi(u_n;\theta_{m'})}_{\mathcal{Y}}\,.
\end{align*}
The first equality in the above display satisfies the upper bound
\begin{align*}
    \sqrt{t}\biggl(\frac{1}{M}\sum_{m=1}^M\abstemp[\bigg]{\frac{1}{M}\sum_{m'=1}^M\alpha_{m'}\beta_{m,m'}^{(N)}}^2\biggr)^{1/2}
    &\leq\sqrt{t}\biggl(\frac{1}{M}\sum_{m=1}^M t \biggl[\frac{1}{M}\sum_{m'=1}^M\abstemp[\big]{\beta_{m,m'}^{(N)}}^2\biggr]\biggr)^{1/2}\\
    &=\frac{t}{N}\sqrt{\frac{1}{M^2}\sum_{m,m'=1}^M\abstemp[\bigg]{\sum_{n=1}^N\varepsilon_n\iptemp{\varphi(u_n;\theta_m)}{\varphi(u_n;\theta_{m'})}_{\mathcal{Y}}}^2}
\end{align*}
by two applications of the Cauchy--Schwarz inequality in $\mathbb{R}^M$. Finally, we deduce that
\begin{align*}
    \eqref{eq:app_loss_sup_3}&\leq \frac{2t}{N}\sqrt{\frac{1}{M^2}\sum_{m,m'=1}^M\sum_{n=1}^N\operatorname{\mathbb{E}}_{{\{u_n\}}}\iptemp[\big]{\varphi(u_n;\theta_m)}{\varphi(u_n;\theta_{m'})}_{\mathcal{Y}}^2}\\
    &\leq \frac{2t}{\sqrt{N}}\sqrt{\frac{1}{M^2}\sum_{m,m'=1}^M\operatorname{\mathbb{E}}_{u}\Bigl[\normtemp{\varphi(u;\theta_m)}_{\mathcal{Y}}^2\normtemp{\varphi(u;\theta_{m'})}_{\mathcal{Y}}^2\Bigr]}\\
    &\leq \frac{2t\normtemp{\varphi}_{L^\infty}^2}{\sqrt{N}}
\end{align*}
by Jensen's inequality, the fact that $\operatorname{\mathbb{E}}[\varepsilon_n\varepsilon_{n'}]=\delta_{n,n'}$, and the Cauchy--Schwarz inequality in $\mathcal{Y}$.

Combining the three estimates completes the proof.

Lem.~\ref{lem:app_loss_sup_con}~and~\ref{lem:app_loss_sup_expect} (applied with $t=\beta$) show that
\begin{equation}\label{eq:app_est_bdd_temp}
\mathcal{E}_\beta({\{u_n\}},{\{\theta_m\}})\leq \frac{4(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 \beta)}{\sqrt{N}}
+ 32e^{3/2}(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 \beta)\sqrt{\frac{\log(1/\delta)}{N}}
\end{equation}
with conditional probability (over ${\{\theta_m\}}$) at least $1-\delta$ if $N\geq \log(1/\delta)$. Since $\delta$ does not depend on ${\{\theta_m\}}$, we deduce by the tower rule of conditional expectation that the event implied by \eqref{eq:app_est_bdd_temp} has $\mathbb{P}$-probability at least $1-\delta$ as well. Using the inequalities $4\leq 32e^{3/2}$ and $\sqrt{a}+\sqrt{b}\leq \sqrt{2(a+b)}$
shows that the expression in \eqref{eq:app_est_bdd_temp} is bounded above by
\begin{equation*}
      32e^{3/2}\bigl(\normtemp{\mathcal{G}}_{L_\nu^\infty}^2 + \normtemp{\varphi}_{L^\infty}^2 \beta\bigr)\sqrt{\frac{2(1+\log(1/\delta))}{N}}\,.
\end{equation*}
Application of the inequality $1\leq 2\log(2/\delta)$, valid for $\delta\in(0,1)$, implies \eqref{eq:app_est_bdd} as asserted.
